      "Comprehension Passage": [
        {
          "slot": "english.B.Q2",
          "main_question": "Read the passage and answer the questions",
          "passage": "On Saturday morning, Ahmed walked to the park with his new red kite. The wind was strong, and the kite flew high into the sky. Ahmed laughed with joy as he watched it dance among the clouds. Suddenly, a gust of wind snapped the string, and the kite sailed away over the trees. Ahmed ran after it, but the kite disappeared behind a tall building. Feeling sad, he sat on a bench and sighed. Just then, a kind old man approached, carrying the very same kite. 'I found this stuck in my garden,' he said with a smile, handing it back to Ahmed. Ahmed thanked him happily and promised to hold the string tighter next time. He flew his kite again until the sun began to set, feeling grateful for the kind stranger's help.",
          "marks": 20,
          "lines": 0,
          "parts": [
            {
              "key": "questions",
              "questions": [
                {
                  "question": "Why did Ahmed go to the park on Saturday morning? (Based on the passage above)",
                  "marks": 2,
                  "lines": 2,
                  "blooms": "Remember",
                  "answer": "He went to fly his new red kite.",
                  "scheme": {
                    "points": [
                      {"text": "States that Ahmed went to fly his new red kite", "marks": 2, "kind": "K"}
                    ],
                    "accept": ["He wanted to fly his kite", "To play with his new kite in the park"],
                    "common_error": "Child writes only 'to play' without mentioning the kite."
                  }
                },
                {
                  "question": "What happened when a gust of wind blew? (Based on the passage above)",
                  "marks": 2,
                  "lines": 2,
                  "blooms": "Remember",
                  "answer": "The string snapped and the kite sailed away over the trees.",
                  "scheme": {
                    "points": [
                      {"text": "States that the string snapped/broke and the kite flew away", "marks": 2, "kind": "K"}
                    ],
                    "accept": ["The kite's string broke and it flew away", "The kite sailed away over the trees"],
                    "common_error": "Child only writes 'the kite flew away' without mentioning the string snapping."
                  }
                },
                {
                  "question": "How do you think Ahmed felt when he lost his kite? Give a reason for your answer. (Based on the passage above)",
                  "marks": 2,
                  "lines": 3,
                  "blooms": "Understand",
                  "answer": "He felt sad because the passage says he sat on a bench and sighed.",
                  "scheme": {
                    "points": [
                      {"text": "Identifies the correct feeling (sad/upset)", "marks": 1, "kind": "U"},
                      {"text": "Gives a valid reason linked to the passage (e.g. he sat and sighed)", "marks": 1, "kind": "A"}
                    ],
                    "accept": ["Sad, because he sighed on the bench", "Upset, because he lost something he loved"],
                    "common_error": "Child states a feeling without giving any supporting reason."
                  }
                },
                {
                  "question": "Who helped Ahmed get his kite back? (Based on the passage above)",
                  "marks": 2,
                  "lines": 2,
                  "blooms": "Remember",
                  "answer": "A kind old man who found it stuck in his garden.",
                  "scheme": {
                    "points": [
                      {"text": "States that a kind old man helped Ahmed", "marks": 2, "kind": "K"}
                    ],
                    "accept": ["An old man found it in his garden and returned it"],
                    "common_error": "Child writes 'a man' without mentioning he was kind/old or found it in the garden."
                  }
                },
                {
                  "question": "What lesson did Ahmed learn from this experience? (Based on the passage above)",
                  "marks": 2,
                  "lines": 3,
                  "blooms": "Understand",
                  "answer": "He learned to hold the string tighter next time so he would not lose his kite again.",
                  "scheme": {
                    "points": [
                      {"text": "States the correct lesson (holding the string tighter/being careful)", "marks": 1, "kind": "U"},
                      {"text": "Connects the lesson to a detail from the passage", "marks": 1, "kind": "A"}
                    ],
                    "accept": ["To hold the string tightly so the kite does not fly away again"],
                    "common_error": "Child gives an unrelated moral not connected to the story."
                  }
                }
              ]
            },
            {
              "key": "do_as_directed",
              "questions": [
                {
                  "question": "What part of speech is the underlined word in this sentence from the passage: \"a kind old man approached\"?",
                  "marks": 1,
                  "lines": 1,
                  "blooms": "Understand",
                  "answer": "Adjective",
                  "scheme": {
                    "points": [
                      {"text": "Correctly identifies 'kind' as an adjective", "marks": 1, "kind": "U"}
                    ],
                    "accept": ["Adjective"],
                    "common_error": "Child confuses 'kind' as a noun (type/sort) instead of an adjective describing the man."
                  }
                },
                {
                  "question": "Change the tense of this sentence from the passage into future tense: \"Ahmed ran after it.\"",
                  "marks": 1,
                  "lines": 1,
                  "blooms": "Apply",
                  "answer": "Ahmed will run after it.",
                  "scheme": {
                    "points": [
                      {"text": "Correctly writes 'Ahmed will run after it' using future tense structure", "marks": 1, "kind": "A"}
                    ],
                    "accept": ["Ahmed will run after it."],
                    "common_error": "Child writes 'Ahmed will ran after it' using incorrect verb form."
                  }
                },
                {
                  "question": "Fill in the blank using the correct word from the passage: Ahmed __________ his kite again until the sun began to set.",
                  "marks": 1,
                  "lines": 1,
                  "blooms": "Remember",
                  "answer": "flew",
                  "scheme": {
                    "points": [
                      {"text": "Writes the correct word 'flew' as given in the passage", "marks": 1, "kind": "K"}
                    ],
                    "accept": ["flew"],
                    "common_error": "Child writes 'fly' instead of the past tense 'flew'."
                  }
                },
                {
                  "question": "Write True or False: Ahmed never found his kite again.",
                  "marks": 1,
                  "lines": 1,
                  "blooms": "Remember",
                  "answer": "False",
                  "scheme": {
                    "points": [
                      {"text": "Writes 'False' as the correct answer", "marks": 1, "kind": "K"}
                    ],
                    "accept": ["False"],
                    "common_error": "Child writes 'True' by misreading the ending of the passage."
                  }
                }
              ]
            },
            {
              "key": "pick",
              "pick": {
                "Nouns": ["kite", "park", "man"],
                "Verbs": ["walked", "flew", "ran"]
              },
              "marks": 6,
              "lines": 2,
              "blooms": "Remember",
              "answer": "Nouns: kite, park, man | Verbs: walked, flew, ran",
              "scheme": {
                "points": [
                  {"text": "Correctly picks 'kite' as a noun from the passage", "marks": 1, "kind": "K"},
                  {"text": "Correctly picks 'park' as a noun from the passage", "marks": 1, "kind": "K"},
                  {"text": "Correctly picks 'man' as a noun from the passage", "marks": 1, "kind": "K"},
                  {"text": "Correctly picks 'walked' as a verb from the passage", "marks": 1, "kind": "K"},
                  {"text": "Correctly picks 'flew' as a verb from the passage", "marks": 1, "kind": "K"},
                  {"text": "Correctly picks 'ran' as a verb from the passage", "marks": 1, "kind": "K"}
                ],
                "accept": ["Any three correctly identified nouns and three correctly identified verbs appearing in the passage"],
                "common_error": "Child confuses a describing word (adjective like 'kind') for a noun or verb."
              }
            }
          ]
        }
      ],
      "Letter Writing": [],
      "Story Writing": [],
      "Essay Writing": [],
      "Other": []
    }
  }
}

