            "points": [
              { "text": "Capitalise 'Rani' at the start and 'Its' after the full stop", "marks": 1, "kind": "A" },
              { "text": "Capitalise the proper nouns 'Jojo' and 'Neem'", "marks": 1, "kind": "A" },
              { "text": "Insert a full stop after 'tree' and after 'fly'", "marks": 1, "kind": "A" },
              { "text": "Insert a comma after 'hurt' before 'and'", "marks": 1, "kind": "A" },
              { "text": "Insert the apostrophe in 'couldn't' and a question mark after 'better'", "marks": 1, "kind": "A" }
