            "accept": ["any correct punctuation and capitalisation that preserves the original meaning"],
            "common_error": "missing capital letters at the start of sentences and proper nouns, or leaving out the apostrophe/question mark"
          }
        }
      ],
      "Word Sentences": [
        {
          "main_question": "Use any FIVE of the following six words in your own sentences. For each word you choose, first write its meaning and then use it correctly in a sentence of your own.",
          "words": ["forgiveness", "annoyance", "responsibility", "sacrifice", "transformation", "democracy"],
          "marks": 10,
          "lines": 10,
          "answer": "forgiveness: letting go of anger towards someone - Pinky showed forgiveness when she forgave her brother for breaking her toy.\nannoyance: a feeling of being irritated - He felt annoyance when his sister messed up his books.\nresponsibility: a duty to take care of something - Feeding the cat every day is Pinky's responsibility.\nsacrifice: giving up something for someone else - She made a sacrifice by sharing her lunch with her hungry friend.\ntransformation: a complete change in form - The caterpillar's transformation into a butterfly amazed everyone.\ndemocracy: a system where people vote to choose leaders - In a democracy, every citizen has the right to vote.",
          "blooms": "Apply",
          "slot": "english.C.Q4",
          "scheme": {
            "points": [
              { "text": "Correct meaning and a grammatically correct original sentence for the 1st chosen word (1 mark meaning + 1 mark sentence)", "marks": 2, "kind": "A" },
              { "text": "Correct meaning and a grammatically correct original sentence for the 2nd chosen word", "marks": 2, "kind": "A" },
              { "text": "Correct meaning and a grammatically correct original sentence for the 3rd chosen word", "marks": 2, "kind": "A" },
              { "text": "Correct meaning and a grammatically correct original sentence for the 4th chosen word", "marks": 2, "kind": "A" },
              { "text": "Correct meaning and a grammatically correct original sentence for the 5th chosen word", "marks": 2, "kind": "A" }
            ],
            "accept": ["any grammatically correct sentence that clearly shows understanding of the word's meaning"],
            "common_error": "using the word incorrectly, giving a vague sentence that does not show meaning, or copying a textbook sentence"
          }
        }
      ],
      "Rhyming Words": [
        {
          "main_question": "Read the poem and match each cue word with its rhyming word from the poem.",
          "question": "Colours",
          "passage": "My skin is kind of sort of brownish pinkish yellowish white.\nMy eyes are greyish blueish green,\nBut I'm told they look orange at night.\nMy hair is reddish blondish brown,\nBut it's silver when it's wet.\nAnd all the colours I am inside\nHave not been invented yet.",
          "words": ["white", "night", "wet", "yet"],
          "marks": 4,
          "lines": 4,
          "answer": "white → night, night → white, wet → yet, yet → wet",
          "blooms": "Understand",
          "slot": "english.C.Q5",
          "scheme": {
            "points": [
              { "text": "white → night", "marks": 1, "kind": "U" },
              { "text": "night → white", "marks": 1, "kind": "U" },
              { "text": "wet → yet", "marks": 1, "kind": "U" },
              { "text": "yet → wet", "marks": 1, "kind": "U" }
            ],
            "accept": ["either direction of the matched pair is acceptable"],
            "common_error": "matching words that sound similar but do not actually rhyme, e.g. matching 'white' with 'wet'"
          }
        }
      ],
      "Mind Map": [
        {
          "main_question": "Draw a mind map on the given topic. Write the topic in the centre and add five branches around it.",
          "question": "Saving the Neem Tree",
          "marks": 5,
          "lines": 0,
          "answer": "Branch 1: Shade and shelter it gives; Branch 2: Home for birds and squirrels; Branch 3: A gathering place for the community; Branch 4: Many generations old; Branch 5: Why it should be protected",
          "blooms": "Create",
          "slot": "english.C.Q6",
          "scheme": {
            "points": [
              { "text": "Any one relevant branch, e.g. shade and shelter the tree provides", "marks": 1, "kind": "A" },
              { "text": "Any one relevant branch, e.g. home for birds and squirrels", "marks": 1, "kind": "A" },
              { "text": "Any one relevant branch, e.g. a gathering place for the community", "marks": 1, "kind": "A" },
              { "text": "Any one relevant branch, e.g. many generations old", "marks": 1, "kind": "A" },
              { "text": "Any one relevant branch, e.g. importance of protecting trees", "marks": 1, "kind": "A" }
            ],
            "accept": ["any five relevant, distinct branches connected logically to the central topic"],
            "common_error": "writing branches that repeat the same idea or are unrelated to the central topic"
          }
        }
      ],
      "Application Writing": [
        {
          "main_question": "Write an application to your principal.",
          "question": "Write an application to your principal requesting leave to attend your brother's marriage ceremony.",
          "marks": 10,
          "lines": 14,
          "answer": "A formal application with sender's address, date, receiver's designation, subject, polite salutation, clear reason (brother's marriage), request for leave with dates, polite closing, signature and class/section.",
          "blooms": "Create",
          "slot": "english.C.Q7",
          "scheme": {
            "points": [
              { "text": "Correct format: address/school name and date", "marks": 2, "kind": "K" },
              { "text": "Appropriate subject line and respectful salutation", "marks": 1, "kind": "K" },
              { "text": "Clear reason for leave (brother's marriage) with relevant details", "marks": 3, "kind": "A" },
              { "text": "Polite request to grant leave for the required days", "marks": 2, "kind": "A" },
              { "text": "Proper closing, signature and class/section details", "marks": 2, "kind": "K" }
            ],
            "accept": ["any correctly formatted application that clearly states the purpose and request"],
            "common_error": "missing the date/address, forgetting the subject line, or not clearly stating the reason for leave"
          }
        },
        {
          "main_question": "Write a letter to your friend.",
          "question": "Write a letter to your friend thanking them for the gift they gave you on your birthday.",
          "marks": 10,
          "lines": 14,
          "answer": "An informal letter with sender's address and date, warm salutation, expression of gratitude describing the gift, feelings about it, and a proper closing with signature.",
          "blooms": "Create",
          "slot": "english.C.Q7",
          "scheme": {
            "points": [
              { "text": "Correct informal letter format: sender's address and date", "marks": 2, "kind": "K" },
              { "text": "Warm and appropriate salutation (Dear...)", "marks": 1, "kind": "K" },
