        }
      ],
      "Paragraph Writing": [
        {
          "main_question": "Write a paragraph on any ONE of the following topics.",
          "topics": ["My Aim in Life", "A Cultural Festival", "Recycling"],
          "marks": 10,
          "lines": 14,
          "answer": "A well-structured paragraph with a topic sentence, 3-5 supporting sentences with relevant facts/ideas, and a concluding sentence, using correct capitalisation and punctuation.",
          "blooms": "Create",
          "slot": "english.C.Q8",
          "scheme": {
            "points": [
              { "text": "Clear topic sentence introducing the chosen theme", "marks": 2, "kind": "A" },
              { "text": "3-5 relevant supporting sentences with facts/ideas", "marks": 4, "kind": "A" },
              { "text": "Correct use of capitalisation and punctuation throughout", "marks": 2, "kind": "K" },
              { "text": "Logical flow using appropriate linking words", "marks": 1, "kind": "A" },
              { "text": "Concluding sentence that wraps up the idea", "marks": 1, "kind": "A" }
            ],
            "accept": ["any well-organised paragraph on one of the given topics that follows topic sentence - supporting details - concluding sentence structure"],
            "common_error": "writing unrelated sentences without a clear topic sentence or concluding sentence"
          }
        }
      ],
      "Story Writing": [
        {
          "main_question": "Write a short story using the given outline. Give it a suitable title and end with the moral clearly stated.",
          "question": "Ali and Sara are best friends — One day Sara accidentally breaks Ali's favourite toy — Ali gets very angry and shouts at her — Sara feels sorry and tries to apologise — Ali refuses to listen and walks away — Ali's grandmother notices he is upset — She tells him a story about the power of forgiveness — Ali thinks about how he would feel in Sara's place — He decides to forgive Sara and accepts her apology — They hug and become friends again — Moral",
          "marks": 5,
          "lines": 10,
          "answer": "A story following the outline in order, using dialogue and descriptive details, ending with a moral such as 'Forgiveness brings happiness and keeps friendships strong.'",
          "blooms": "Create",
          "slot": "english.C.Q9",
          "scheme": {
            "points": [
              { "text": "Correct sequencing of the given cues into a complete story", "marks": 2, "kind": "A" },
              { "text": "Use of appropriate dialogue and descriptive details", "marks": 1, "kind": "A" },
              { "text": "Grammatically correct sentences with correct tense", "marks": 1, "kind": "K" },
